/**
 * An image file on disk.
 *
 * `src` is the compressed preview used everywhere a photo appears in a grid or
 * the pile; `fullSrc` is the web master, served whole when a photo is opened.
 * `width` and `height` are the full photo's displayed dimensions -- the preview
 * shares the same ratio, which is all the frames need. `settings` is whatever
 * the camera recorded, absent if the file carried no tags.
 */
export interface PhotoSettings {
  iso?: string
  aperture?: string
  shutter?: string
}

export interface PhotoFile {
  src: string
  fullSrc: string
  width: number
  height: number
  settings?: PhotoSettings
}

export interface CollectionPhotoFile extends PhotoFile {
  id: string
}

/**
 * The home page's opening photograph, or null until one is dropped into
 * public/photos/home/. Two renditions of the same picture, each with its own
 * pixel width so the browser can pick on what the slot actually asks for;
 * `width` and `height` are the original's, which is never served.
 */
export interface HeroFile {
  src: string
  srcWidth: number
  src2x: string
  src2xWidth: number
  width: number
  height: number
}

